CREATE OR REPLACE FUNCTION public.social_product_visible(_kind text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE _kind WHEN 'course' THEN EXISTS(SELECT 1 FROM public.courses WHERE id=_id AND status='published') WHEN 'ebook' THEN EXISTS(SELECT 1 FROM public.ebooks WHERE id=_id AND status='published') WHEN 'session' THEN EXISTS(SELECT 1 FROM public.class_sessions WHERE id=_id AND status='scheduled') WHEN 'plan' THEN EXISTS(SELECT 1 FROM public.membership_plans WHERE id=_id AND status='published') ELSE false END $$;
REVOKE ALL ON FUNCTION public.social_product_visible(text,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.social_product_visible(text,uuid) TO anon,authenticated,service_role;
CREATE TABLE public.product_likes(product_kind text NOT NULL CHECK(product_kind IN('course','ebook','session','plan')),product_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(id),created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(product_kind,product_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.product_likes TO authenticated; GRANT ALL ON public.product_likes TO service_role;
ALTER TABLE public.product_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own likes read" ON public.product_likes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "own likes add" ON public.product_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.social_product_visible(product_kind,product_id) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active'));
CREATE POLICY "own likes remove" ON public.product_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.product_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),product_kind text NOT NULL CHECK(product_kind IN('course','ebook','session','plan')),product_id uuid NOT NULL,user_id uuid NOT NULL REFERENCES public.profiles(id),body text NOT NULL CHECK(length(btrim(body)) BETWEEN 1 AND 1000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,DELETE ON public.product_comments TO authenticated; GRANT ALL ON public.product_comments TO service_role;
ALTER TABLE public.product_comments ENABLE ROW LEVEL SECURITY;
CREATE INDEX product_comments_listing ON public.product_comments(product_kind,product_id,created_at DESC);
CREATE POLICY "own comments read" ON public.product_comments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "own comments add" ON public.product_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND public.social_product_visible(product_kind,product_id) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active'));
CREATE POLICY "own or admin comments remove" ON public.product_comments FOR DELETE TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.product_social_summary(_kind text,_id uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('likes',CASE WHEN public.social_product_visible(_kind,_id) THEN (SELECT count(*) FROM public.product_likes WHERE product_kind=_kind AND product_id=_id) ELSE 0 END,'comments',CASE WHEN public.social_product_visible(_kind,_id) THEN (SELECT count(*) FROM public.product_comments WHERE product_kind=_kind AND product_id=_id) ELSE 0 END) $$;
REVOKE ALL ON FUNCTION public.product_social_summary(text,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.product_social_summary(text,uuid) TO anon,authenticated,service_role;
CREATE OR REPLACE FUNCTION public.product_comment_feed(_kind text,_id uuid,_offset integer DEFAULT 0) RETURNS TABLE(id uuid,body text,created_at timestamptz,author text,is_own boolean) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT c.id,c.body,c.created_at,coalesce(nullif(p.full_name,''),'Student'),coalesce(c.user_id=auth.uid(),false) FROM public.product_comments c JOIN public.profiles p ON p.id=c.user_id WHERE c.product_kind=_kind AND c.product_id=_id AND public.social_product_visible(_kind,_id) ORDER BY c.created_at DESC,c.id LIMIT 20 OFFSET greatest(0,least(_offset,10000)) $$;
REVOKE ALL ON FUNCTION public.product_comment_feed(text,uuid,integer) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.product_comment_feed(text,uuid,integer) TO anon,authenticated,service_role;